"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type AnticipationPrimitiveProps = ComponentProps<typeof motion.div>;

export function AnticipationPrimitive({ children, ...props }: AnticipationPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {x: 0,scale: 1}}
      animate={{x: [0,-5.76,32,3.84,0],scale: [1,0.982,1.012,1]}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.52, ease: [0.16, 1, 0.3, 1] }}

    >
      {children}
    </motion.div>
  );
}
